import chess

MOTIF_NAME = 'piece_fork_potential'
MOTIF_DESCRIPTION = 'Side to move has a piece attacking two or more opponent pieces.'

def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    piece_types = [chess.PAWN, chess.KNIGHT, chess.BISHOP, chess.ROOK, chess.QUEEN]

    for piece_type in piece_types:
        for sq in board.pieces(piece_type, stm):
            attacks = board.attacks(sq)
            count = 0
            for attack_sq in attacks:
                piece = board.piece_at(attack_sq)
                if piece and piece.color == opp:
                    count += 1
            if count >= 2:
                return True

    return False
